-- Rams: generated by tools/build.py from colors.toml.
-- Honest surfaces: no blur, no shadow, no translucency. The active window
-- gets a charcoal edge, the rest a quiet grey. Groups mark the active
-- tab with Braun orange. Motion is short and eased out, with no overshoot.

local active = "rgb(3a3935)"
local inactive = "rgb(d3cec4)"

hl.config({
  general = {
    border_size = 2,
    col = {
      active_border = active,
      inactive_border = inactive,
    },
  },

  decoration = {
    rounding = 6,
    rounding_power = 2,
    active_opacity = 1.0,
    inactive_opacity = 1.0,
    dim_inactive = false,
    shadow = { enabled = false },
    blur = { enabled = false },
  },

  group = {
    col = {
      border_active = active,
      border_inactive = inactive,
      border_locked_active = active,
      border_locked_inactive = inactive,
    },
    groupbar = {
      font_family = "ABC Areal",
      font_size = 11,
      font_weight_active = "medium",
      font_weight_inactive = "normal",
      height = 20,
      indicator_height = 2,
      gradients = false,
      text_color = "rgb(2b2a27)",
      text_color_inactive = "rgb(797773)",
      col = {
        active = "rgb(d4521c)",
        inactive = "rgb(d3cec4)",
      },
    },
  },

  misc = {
    background_color = "rgb(eeebe5)",
  },
})

-- Opaque windows. Omarchy's default is slightly translucent; a Braun object
-- does not pretend to be glass.
o.window({ tag = "default-opacity" }, { opacity = "1.0 1.0" })
o.window({ tag = "terminal" }, { opacity = "1.0 1.0" })

-- Calm motion: one ease-out curve, short durations, no bounce or slide-in.
hl.curve("rams", { type = "bezier", points = { { 0.2, 0.0 }, { 0.0, 1.0 } } })
hl.animation({ leaf = "windows", enabled = true, speed = 2.6, bezier = "rams" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 2.4, bezier = "rams", style = "popin 96%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.6, bezier = "rams", style = "popin 96%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 2.6, bezier = "rams" })
hl.animation({ leaf = "border", enabled = true, speed = 2.0, bezier = "rams" })
hl.animation({ leaf = "fade", enabled = true, speed = 2.0, bezier = "rams" })
hl.animation({ leaf = "layers", enabled = true, speed = 2.4, bezier = "rams" })
hl.animation({ leaf = "layersIn", enabled = true, speed = 2.4, bezier = "rams", style = "fade" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 1.6, bezier = "rams", style = "fade" })
